j:jelly.script:
// show link if populated, hide if not
function onChange_${jvar_guid}(element, original, changed, loading) {
    var visibility = 'hidden';
    if (changed.length > 0)
        visibility = 'visible';
    var e = gel('${jvar_n}');
    e.style.visibility = visibility;
}

// show schedule if the sys_id is populated
function showSchedule(name) {
    var fieldName = name.split(':')[1];
    var n = gel(fieldName);
    n = n.value;
    if (n.length == 0) {
        alert(new GwtMessage().getMessage("A schedule must be specified first"));
    } else {
        showSchedulePopup(n, fieldName);
    }
}

// generic show schedule function for sys_id
function showSchedulePopup(sys_id, fieldName) {
    var url = 'show_schedule.do?sysparm_stack=no';
    url += '&amp;';
    url += 'sysparm_sys_id=' + sys_id;
    url += '&amp;';
    url += 'sysparm_include_view=monthly,weekly,daily,oldtimeline';
    g_navigation.open(url, '_blank ');
}

// create the onchange handler
var h = new GlideEventHandler('onChange_${jvar_guid}', onChange_${jvar_guid}, '${ref}');
g_event_handlers.push(h);
